mod solution;use solution::metric_rollup;#[test]fn contract(){assert_eq!(metric_rollup("cpu=2;mem=3;cpu=4"),Some("cpu=6;mem=3".to_string()));
assert_eq!(metric_rollup("a=0"),Some("a=0".to_string()));
assert_eq!(metric_rollup("cpu=01"),None);
assert_eq!(metric_rollup("cpu=-1"),None);
assert_eq!(metric_rollup("cpu=+1"),None);
assert_eq!(metric_rollup("a--b=1"),None);
assert_eq!(metric_rollup("x=9223372036854775807;x=1"),None);
assert_eq!(metric_rollup("=1"),None);}
